/**
 * Neutralises the default path in the glue generated by wasm-bindgen.
 *
 * wasm-bindgen emits `new URL('crypto_wasm_bg.wasm', import.meta.url)` as a fallback. That path
 * is never taken — `loadCrypto()` always passes an explicit URL — but bundlers analyse it
 * statically and fail to resolve the file, which lives in `public/` and not next to the module.
 *
 * It is replaced by a speaking error rather than deleted: if someone ever calls `init()` with no
 * argument, they should get a clear message, not an obscure failure.
 */
import { readFileSync, writeFileSync } from "node:fs";

const FILE = "src/lib/generated/crypto_wasm.js";
const NEEDLE = "module_or_path = new URL('crypto_wasm_bg.wasm', import.meta.url);";
const REPLACEMENT =
  "throw new Error('The WASM module path is required — see loadCrypto() in src/lib/wasm.ts');";

const source = readFileSync(FILE, "utf8");

if (!source.includes(NEEDLE)) {
  if (source.includes(REPLACEMENT)) process.exit(0);
  // A wasm-bindgen version bump changed the glue: better to break the build loudly than to let
  // a patch that has silently become a no-op slip through.
  console.error(`Pattern not found in ${FILE} — the wasm-bindgen glue has changed.`);
  process.exit(1);
}

writeFileSync(FILE, source.replace(NEEDLE, REPLACEMENT));
